import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, useNavigate } from 'react-router-dom';
import { toast } from '../libs/toast';

const toPersianDigits = (str: string | number) => {
  const s = String(str);
  const d = ['۰','۱','۲','۳','۴','۵','۶','۷','۸','۹'];
  return s.replace(/[0-9]/g, (w) => d[+w]);
};

const EstimateDetail: React.FC = () => {
  const { id } = useParams();
  const [estimate, setEstimate] = useState<any>(null);
  const [roles, setRoles] = useState<any[]>([]);
  const [savingRoleId, setSavingRoleId] = useState<number | null>(null);
  const [programs, setPrograms] = useState<any[]>([]);
  const navigate = useNavigate();

  useEffect(() => { fetchPrograms(); }, []);
  useEffect(() => { if (id) fetchEstimate(); }, [id]);

  const fetchPrograms = async () => {
    try { const res = await axios.get('/api/programs'); setPrograms(res.data); }
    catch { /* ignore */ }
  };

  const fetchEstimate = async () => {
    try {
      const res = await axios.get(`/api/estimates/${id}`);
      setEstimate(res.data.estimate);
      setRoles(res.data.roles || []);
    } catch {
      toast.error('دریافت جزئیات برآورد با خطا مواجه شد');
    }
  };

  const token = localStorage.getItem('token');
  const authHeaders = token ? { Authorization: `Bearer ${token}` } : undefined;

  const updateRoleWage = async (row: any) => {
    if (!id) return;
    setSavingRoleId(row.id);
    const payload: any = {
      role_id: row.role_id || null,
      role_code: row.role_code || null,
      role_name: row.role_name || null,
      wage_amount: row.wage_amount || null,
      wage_percent: row.wage_percent || null,
    };
    try {
      await axios.post(`/api/estimates/${id}/roles`, payload, { headers: authHeaders });
      toast.success('دستمزد نقش به‌روزرسانی شد');
    } catch {
      toast.error('به‌روزرسانی دستمزد با خطا مواجه شد');
    } finally {
      setSavingRoleId(null);
    }
  };

  if (!estimate) {
    return <div className="loading-container"><div className="loading-spinner"></div><p>در حال بارگذاری...</p></div>;
  }

  const prog = programs.find((p) => p.id === estimate.program_id);
  const totalMinutes = (estimate.program_count || 0) * (estimate.duration_minutes || 0);
  const totalAmount = totalMinutes * (estimate.minute_rate || 0);

  return (
    <div className="page-container">
      <div className="page-header">
        <h1>جزئیات برآورد {estimate.estimate_code}</h1>
        <button className="btn" onClick={() => navigate('/estimates')}>بازگشت</button>
      </div>

      <div className="form-card">
        <div className="info-grid">
          <div><strong>برنامه:</strong> {prog ? prog.name : '—'}</div>
          <div><strong>مدت هر برنامه:</strong> {toPersianDigits(estimate.duration_minutes)} دقیقه</div>
          <div><strong>تعداد برنامه:</strong> {toPersianDigits(estimate.program_count)}</div>
          <div><strong>نرخ هر دقیقه:</strong> {toPersianDigits(estimate.minute_rate)} تومان</div>
          <div><strong>دقیقه کل:</strong> {toPersianDigits(totalMinutes)}</div>
          <div><strong>مبلغ کل:</strong> {toPersianDigits(totalAmount)}</div>
          <div><strong>پذیرایی:</strong> {toPersianDigits(estimate.hospitality_cost || 0)}</div>
          <div><strong>ایاب و ذهاب:</strong> {toPersianDigits(estimate.transport_cost || 0)}</div>
          <div><strong>متفرقه:</strong> {toPersianDigits(estimate.misc_cost || 0)}</div>
          <div><strong>تاریخ ثبت:</strong> {estimate.created_at?.slice(0, 10) || '—'}</div>
          <div><strong>انقضا:</strong> {estimate.expiration_date?.slice(0, 10) || '—'}</div>
        </div>
        {estimate.linked_to_estimate_id && (
          <div className="hint-row">پیوست به برآورد: {estimate.linked_to_estimate_id}</div>
        )}
      </div>

      <div className="list-card">
        <h2>نقش‌ها و دستمزدها</h2>
        {roles.length === 0 ? (
          <p>نقشی برای این برآورد ثبت نشده است.</p>
        ) : (
          <table className="data-table">
            <thead>
              <tr>
                <th>نقش</th>
                <th>کد نقش</th>
                <th>دستمزد عددی</th>
                <th>دستمزد درصدی</th>
                <th>شناسه نقش</th>
                <th>ذخیره</th>
              </tr>
            </thead>
            <tbody>
              {roles.map((r) => (
                <tr key={r.id}>
                  <td>{r.role_name || '—'}</td>
                  <td>{r.role_code || '—'}</td>
                  <td>
                    <input
                      type="number"
                      value={r.wage_amount || ''}
                      onChange={(e) => setRoles((rows) => rows.map((rw) => rw.id === r.id ? { ...rw, wage_amount: e.target.value ? Number(e.target.value) : null } : rw))}
                      style={{ width: 120 }}
                    />
                  </td>
                  <td>
                    <input
                      type="number"
                      value={r.wage_percent || ''}
                      onChange={(e) => setRoles((rows) => rows.map((rw) => rw.id === r.id ? { ...rw, wage_percent: e.target.value ? Number(e.target.value) : null } : rw))}
                      style={{ width: 80 }}
                    />
                  </td>
                  <td>{r.role_id || '—'}</td>
                  <td>
                    <button className="btn" onClick={() => updateRoleWage(r)} disabled={savingRoleId === r.id}>
                      {savingRoleId === r.id ? 'در حال ذخیره…' : 'ذخیره'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

export default EstimateDetail;
